-- Crear tabla con descripciones completas
CREATE TABLE [dbo].[tarjetas] (
    [CODENT] NVARCHAR(4) NULL,
    [CODMAR] TINYINT NULL,
    [INDTIPT] TINYINT NULL,
    [CENTALTA] NVARCHAR(4) NULL,
    [CUENTA] NVARCHAR(12) NULL,
    [CALPART] NVARCHAR(2) NULL,
    [IDENTCLI] NVARCHAR(8) NULL,
    [TIPBON] NVARCHAR(6) NULL,
